from dsl import *

LESSON = {
    "id": "l23",
    "label": "23",
    "title": "Who, which and that",
    "summary": "Using the ligatures -ng, -g and na to say the child who is eating, the house which was burned, the food that was cooked",
    "minutes": 25,
    "goals": [
        "See how a ligature does the job of English who, which and that",
        "Join a noun and a verb in either order: ang batàng kumakain or ang kumakaing batà",
        "Read and build sentences such as Maliít ang sapátos na binilí ko",
        "Link a person's name to a verb, preferring na: Si Pedro na umáawit",
    ],
    "sections": [
        S("Ligatures as who, which and that",
          P("English uses **relative pronouns** such as *who*, *which* and *that* to connect a description to a noun that comes before it: *the child **who** is eating*."),
          P("Tagalog does the same job with a **ligature** (**-ng**, **-g** and **na**). The ligature connects a noun or pronoun to a **verb** (or the verb to the noun), and the result is a phrase that works like a relative pronoun. The rules for choosing the ligature are the ones from **Lesson 7** (Words that Link and Describe)."),
          BOX("remember", "Ligature rules from Lesson 7", items=[
              "Word ends in a **vowel**: add **-ng** (batà → batà**ng**).",
              "Word ends in **n**: add **-g** (pagkain → pagkain**g**).",
              "Word ends in another **consonant**: use **na** as a separate word (báhay **na**)."]),
          PAT("Noun + ligature + verb",
              [("Noun first", [("ang", "marker"), ("batà", "noun"), ("-ng", "link"), ("kumakain", "pred")]),
               ("Verb first", [("ang", "marker"), ("kumakain", "pred"), ("-g", "link"), ("batà", "noun")])],
              note="the child who is eating"),
          P("As in Lesson 7, **changing the order** of the noun (or pronoun) and the verb **does not change the meaning**."),
          TABLE(["Noun first", "Verb first", "Meaning"],
                [["ang batà[[ng|link]] kumakain", "ang kumakain[[g|link]] batà", "the child **who** is eating"],
                 ["ang báhay [[na|link]] nasúnog", "ang nasúnog [[na|link]] báhay", "the house **which** was burned"],
                 ["ang pagkain[[g|link]] nilutò", "ang nilutò[[ng|link]] pagkain", "the food **that** was cooked"]],
                title="The ligature stands for who, which, that"),
          VOC("verbs", "Verb forms in this lesson")),

        S("Sample sentences",
          EXS([("Ang súlat na tinanggáp ko ay kanyá.", "The letter that I received was his/hers.",
                [("Ang", "article", "marker"), ("súlat", "letter", "noun"), ("na", "that", "link"), ("tinanggáp", "received", "pred"), ("ko", "I", "poss"), ("ay", "(links)", "ay"), ("kanyá", "his/hers", "poss")]),
               ("Maliít ang sapátos na binilí ko.", "The shoes that I bought were small.",
                [("Maliít", "small", "pred"), ("ang", "article", "marker"), ("sapátos", "shoes", "noun"), ("na", "that", "link"), ("binilí", "bought", "pred"), ("ko", "I", "poss")]),
               ("Kamíng nag-áaral ang ináabala mo.", "We who are studying are being disturbed by you. (literal)",
                [("Kamíng", "we who (+ng)", "pron"), ("nag-áaral", "are studying", "pred"), ("ang", "article", "marker"), ("ináabala", "being disturbed", "pred"), ("mo", "by you", "poss")]),
               ("Magagandá ang mga babáeng umáawit.", "The women who are singing are beautiful.",
                [("Magagandá", "beautiful (plural)", "pred"), ("ang", "article", "marker"), ("mga", "plural", "marker"), ("babáeng", "women who (+ng)", "noun"), ("umáawit", "are singing", "pred")]),
               ("Ang laláking natútulog ay ginígising ng batà.", "The man who is sleeping is being awakened by the child.",
                [("Ang", "article", "marker"), ("laláking", "man who (+ng)", "noun"), ("natútulog", "is sleeping", "pred"), ("ay", "(links)", "ay"), ("ginígising", "being awakened", "pred"), ("ng", "by", "marker"), ("batà", "child", "noun")]),
               ("Ang mga tinátawag mo ay iyóng mga umáalis.", "The ones that you are calling are those who are leaving.",
                [("Ang", "article", "marker"), ("mga", "plural", "marker"), ("tinátawag", "being called", "pred"), ("mo", "by you", "poss"), ("ay", "(links)", "ay"), ("iyóng", "those who (+ng)", "pron"), ("mga", "plural", "marker"), ("umáalis", "are leaving", "pred")])],
              title="Who, which and that in sentences"),
          BOX("tip", "Find the ligature", t="In each sentence, look for the **-ng** or **na** that joins a noun or pronoun to a verb: súlat **na** tinanggáp, sapátos **na** binilí, kamí**ng** nag-áaral, babáe**ng** umáawit, laláki**ng** natútulog, iyó**ng** mga umáalis. That ligature is the English *who / which / that*.")),

        S("With names of people",
          P("When the subject is a **person's name**, it is not wrong to attach **-ng** or **-g** to the name:"),
          EXS([("Si Pedrong umáawit ay kaibígan ko.", "Pedro, the one who sings, is my friend.",
                [("Si", "(before a name)", "marker"), ("Pedrong", "Pedro who (+ng)", "noun"), ("umáawit", "sings", "pred"), ("ay", "(links)", "ay"), ("kaibígan", "friend", "noun"), ("ko", "my", "poss")]),
               ("Si Juang sumulat nitong kuwento ay may sakít.", "Juan, the (one) who wrote this story, is sick.",
                [("Si", "(before a name)", "marker"), ("Juang", "Juan who (+g)", "noun"), ("sumulat", "wrote", "pred"), ("nitong", "this (+ng)", "other"), ("kuwento", "story", "noun"), ("ay", "(links)", "ay"), ("may", "has", "other"), ("sakít", "sickness", "noun")])],
              title="Not wrong"),
          P("However, using the ligature **na** after a person's name is **more common**:"),
          EXS([("Si Pedro na umáawit ay kaibígan ko.", "Pedro, the one who sings, is my friend. (same meaning as Si Pedrong umáawit…)",
                [("Si", "(before a name)", "marker"), ("Pedro", "Pedro", "noun"), ("na", "who", "link"), ("umáawit", "sings", "pred"), ("ay", "(links)", "ay"), ("kaibígan", "friend", "noun"), ("ko", "my", "poss")]),
               ("Si Juan na sumulat nito ay may sakít.", "Juan, the (one) who wrote this, is sick. (same meaning as Si Juang sumulat…)",
                [("Si", "(before a name)", "marker"), ("Juan", "Juan", "noun"), ("na", "who", "link"), ("sumulat", "wrote", "pred"), ("nito", "this", "other"), ("ay", "(links)", "ay"), ("may", "has", "other"), ("sakít", "sickness", "noun")])],
              title="More common: na after a name"),
          BOX("remember", "Remember", items=[
              "A ligature (-ng, -g, na) joining a noun and a verb = who, which or that.",
              "Choose the ligature with the Lesson 7 rules: vowel → -ng, n → -g, other consonant → na.",
              "Noun first or verb first, the meaning is the same: ang báhay na nasúnog = ang nasúnog na báhay.",
              "After a person's name, na is more common: Si Pedro na umáawit."])),
    ],
    "vocab": [
        V("nasunog-l23", "nasúnog", "burned", say="na-SU-nog", pos="verb", group="verbs"),
        V("tinanggap-l23", "tinanggáp", "received", say="ti-nang-GAP", pos="verb", group="verbs"),
        V("ginigising-l23", "ginígising", "being awakened", say="gi-NI-gi-sing", pos="verb", group="verbs"),
        V("niluto-l23", "nilutò", "cooked", say="ni-LU-toQ", pos="verb", group="verbs"),
        V("inaabala-l23", "ináabala", "being disturbed", say="i-NA-a-ba-la", pos="verb", group="verbs"),
        V("tinatawag-l23", "tinátawag", "being called", say="ti-NA-ta-wag", pos="verb", group="verbs"),
        V("binili-l23", "binilí", "bought", say="bi-ni-LI", pos="verb", group="verbs"),
        V("umaawit-l23", "umáawit", "singing; sings", say="u-MA-a-wit", pos="verb", group="verbs"),
        V("umaalis-l23", "umáalis", "leaving", say="u-MA-a-lis", pos="verb", group="verbs"),
        V("sumulat-l23", "sumulat", "wrote", pos="verb", group="verbs"),
        V("isusuot-l23", "isusuót", "will wear", say="i-su-su-OT", pos="verb", group="verbs"),
    ],
    "exercises": [
        CH("In this lesson, what does the job of English who, which and that?", ["a ligature (-ng, -g, na)", "the word ay", "the marker ang"], "a ligature (-ng, -g, na)", "The ligature joins the noun or pronoun to the verb."),
        CH("\"ang batàng kumakain\" means…", ["the child who is eating", "the food that was cooked", "the child is eating"], "the child who is eating", "Batà + -ng + kumakain."),
        CH("Which means the same as \"ang báhay na nasúnog\"?", ["ang nasúnog na báhay", "ang báhay nasúnog", "ang nasúnog báhay"], "ang nasúnog na báhay", "Changing the order does not change the meaning."),
        CH("Which means the same as \"ang pagkaing nilutò\"?", ["ang nilutòng pagkain", "ang nilutò na pagkain", "ang pagkain nilutò"], "ang nilutòng pagkain", "Nilutò ends in a vowel, so it takes -ng."),
        CH("Fill in: ang báhay ___ nasúnog", ["na", "-ng", "-g"], "na", "Báhay ends in a consonant (y), so na is used."),
        CH("Join kumakain and batà, verb first (the child who is eating).", ["ang kumakaing batà", "ang kumakain na batà", "ang kumakainng batà"], "ang kumakaing batà", "Kumakain ends in n, so add -g."),
        CH("Fill in: Maliít ang sapátos ___ binilí ko.", ["na", "-ng", "ang"], "na", "Sapátos ends in s, so na is used."),
        CH("\"Ang súlat na tinanggáp ko ay kanyá\" means…", ["The letter that I received was his/hers.", "The letter that I wrote was his/hers.", "I received his/her letter."], "The letter that I received was his/hers.", "Tinanggáp = received."),
        CH("\"Magagandá ang mga babáeng umáawit\" means…", ["The women who are singing are beautiful.", "The beautiful women will sing.", "The women sang beautifully."], "The women who are singing are beautiful.", "Babáe + -ng + umáawit."),
        CH("\"Ang laláking natútulog ay ginígising ng batà\" means…", ["The man who is sleeping is being awakened by the child.", "The child who is sleeping is being awakened by the man.", "The man is waking the child."], "The man who is sleeping is being awakened by the child.", "Ginígising = being awakened."),
        CH("Which is more common after a person's name?", ["Si Pedro na umáawit", "Si Pedrong umáawit"], "Si Pedro na umáawit", "Si Pedrong umáawit is not wrong, but na is more common."),
        CH("\"Kamíng nag-áaral ang ináabala mo\" means (literally)…", ["We who are studying are being disturbed by you.", "You are studying and we disturb you.", "We are disturbing your studies."], "We who are studying are being disturbed by you.", "Kamí + -ng + nag-áaral."),
        CH("What does isusuót mean?", ["will wear", "will cook", "was burned"], "will wear", "From the book's exercise: the dress which she will wear (isusuót)."),
        CH("Which ligature is joined to Juan in \"Si Juang sumulat…\"?", ["-g", "-ng", "na"], "-g", "Juan ends in n, so -g is added."),
        LI("nasúnog", ["burned", "cooked", "received"], "burned", "Ang báhay na nasúnog."),
        LI("tinátawag", ["being called", "being disturbed", "being awakened"], "being called", "Ang mga tinátawag mo…"),
        LI("ináabala", ["being disturbed", "being called", "leaving"], "being disturbed", "Kamíng nag-áaral ang ináabala mo."),
        LI("nilutò", ["cooked", "bought", "burned"], "cooked", "Ang pagkaing nilutò."),
        BU("The letter that I received was his/hers.", "Ang súlat na tinanggáp ko ay kanyá."),
        BU("The shoes that I bought were small.", "Maliít ang sapátos na binilí ko."),
        BU("The women who are singing are beautiful.", "Magagandá ang mga babáeng umáawit."),
        BU("The man who is sleeping is being awakened by the child.", "Ang laláking natútulog ay ginígising ng batà."),
        BU("Pedro, the one who sings, is my friend.", "Si Pedro na umáawit ay kaibígan ko."),
        BU("The ones that you are calling are those who are leaving.", "Ang mga tinátawag mo ay iyóng mga umáalis."),
        MA("Match each phrase to its meaning.", [("ang batàng kumakain", "the child who is eating"), ("ang báhay na nasúnog", "the house which was burned"), ("ang pagkaing nilutò", "the food that was cooked"), ("ang sapátos na binilí ko", "the shoes that I bought")]),
        MA("Match each verb to its meaning.", [("tinanggáp", "received"), ("ginígising", "being awakened"), ("umáalis", "leaving"), ("binilí", "bought"), ("sumulat", "wrote")]),
    ],
    "recap": [
        "A ligature (-ng, -g, na) joining a noun or pronoun and a verb works like who, which or that.",
        "Use the Lesson 7 rules: vowel → -ng, n → -g, other consonant → na.",
        "The order can swap without changing the meaning: ang batàng kumakain = ang kumakaing batà.",
        "Maliít ang sapátos na binilí ko. The shoes that I bought were small.",
        "After a name, -ng/-g is not wrong, but na is more common: Si Pedro na umáawit ay kaibígan ko.",
    ],
}
